      for(int i=0;i<N;i++) if(f[i]!=arrs[t][i]) ok=false;
      if(!ok){
        printf("MISMATCH n=%d t=%d L=%d P=%d Q=%d\nops=",n,t,L,P,Q);
        for(int o:ops) printf("%c", o?'B':'A');
        printf("\np="); for(auto v:p)printf(" %lld",v);
